// Vendor the socket.io-client browser ESM bundle into web/vendor/socket.io/.
//
// Remote mode (index.html's bootRemote) connects the web client to a real
// nxvim-server through the nxvim-web-bridge over Socket.IO. The browser side of
// that transport is socket.io-client; we copy its prebuilt ESM bundle out of the
// pinned npm package so the page loads it from the bridge's own embedded web/
// tree (rust-embed serves anything under web/vendor/) — no runtime CDN, same as
// the tree-sitter vendor. web/vendor/ is gitignored, regenerated by build.sh.
//
// Only the remote boot path dynamic-imports this file; local (serverless) mode
// never touches it, so a static-file checkout without the vendor dir still works.

import { mkdirSync, copyFileSync, existsSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..'); // crate dir
const SRC = join(ROOT, 'node_modules', 'socket.io-client', 'dist');
const OUT = join(ROOT, 'web', 'vendor', 'socket.io');

// The browser ESM build + its sourcemap. Fail loud if the package layout moved
// (a version bump) rather than silently shipping a page that can't boot remote.
const FILES = ['socket.io.esm.min.js', 'socket.io.esm.min.js.map'];
const missing = FILES.filter((f) => !existsSync(join(SRC, f)));
if (missing.length) {
  console.error(
    `vendor-socketio: missing ${missing.join(', ')} in ${SRC}\n` +
      'Run `npm ci` (or `npm install`) first; if the file names changed, the ' +
      'socket.io-client dist layout moved — update this script and index.html.',
  );
  process.exit(1);
}

mkdirSync(OUT, { recursive: true });
for (const f of FILES) copyFileSync(join(SRC, f), join(OUT, f));
console.log(`vendored socket.io-client → web/vendor/socket.io/ (${FILES.join(', ')})`);
